export class SutramDataClient{constructor(t){this.provider=t}async get(t,e={}){return this.provider.get(t,e)}async post(t,e={},r={}){return this.provider.post(t,e,r)}async delete(t,e={}){return this.provider.delete(t,e)}}export class HttpProvider{constructor(t=window.fetch){this.fetchImpl=t}async get(t,e={}){return this.fetchImpl(t,{...e,method:"GET"})}async post(t,e={},r={}){const s=e instanceof FormData,c=s?r.headers||{}:{"Content-Type":"application/json",...r.headers||{}},o=s?e:JSON.stringify(e);return this.fetchImpl(t,{...r,method:"POST",headers:c,body:o})}async delete(t,e={}){return this.fetchImpl(t,{...e,method:"DELETE"})}}
